def time_until_trains_sync():
    train_a_interval = 16
    train_b_interval = 17

    # Find the least common multiple (LCM) of the two intervals
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    def lcm(x, y):
        return x * y // gcd(x, y)

    time_until_sync = lcm(train_a_interval, train_b_interval)
    return time_until_sync

